{
  "title": "Is version B really better?",
  "setting": "Day 1 at Aurora Shop",
  "mission": "Decide whether the early gap between two checkout versions is more than chance. Recommend **whether to launch B, keep testing, or hold off**.",
  "deadline": "Checkout review with {{product}} today at 3:00 p.m.",
  "panels": [
    {
      "title": "Early A/B test",
      "metrics": [
        {
          "label": "Visitors to A",
          "value": "800",
          "note": null
        },
        {
          "label": "Purchases with A",
          "value": "32",
          "note": "4.0% conversion"
        },
        {
          "label": "Visitors to B",
          "value": "800",
          "note": null
        },
        {
          "label": "Purchases with B",
          "value": "40",
          "note": "5.0% conversion"
        }
      ],
      "note": "Versions were randomly assigned; results are from the first day."
    }
  ],
  "team": [
    {
      "id": "data",
      "role": "Data analyst",
      "expertise": "She checks experiment methods and helps teams tell a real difference from chance.",
      "ai": false
    },
    {
      "id": "product",
      "role": "Product manager",
      "expertise": "He owns the checkout launch and wants a timely decision for the team.",
      "ai": false
    },
    {
      "id": "ai",
      "role": "AI assistant",
      "expertise": "It can check calculations and estimate sample sizes, but people review the results and make the call.",
      "ai": true
    }
  ],
  "meters": [
    {
      "id": "risk",
      "label": "Risk of a wrong call",
      "start": 55,
      "goodWhen": "low"
    },
    {
      "id": "pressure",
      "label": "Launch pressure",
      "start": 70,
      "goodWhen": "low"
    },
    {
      "id": "credibility",
      "label": "Decision credibility",
      "start": 50,
      "goodWhen": "high"
    }
  ],
  "skills": [
    {
      "id": "chance",
      "name": "Tell signal from chance",
      "practice": "Explain in one sentence why a gap in two small groups might be due to chance."
    },
    {
      "id": "sample",
      "name": "Choose a sample size",
      "practice": "Estimate how many observations a small comparison would need before you make a decision."
    },
    {
      "id": "explain",
      "name": "Explain a test result",
      "practice": "Explain one test result to someone who isn't a data person, in one sentence."
    }
  ],
  "startNodeId": "start",
  "nodes": [
    {
      "id": "start",
      "messages": [
        {
          "from": "product",
          "text": "B has 5.0% conversion and A has 4.0%. That's 25% more purchases per visitor for B. Can we launch it today?"
        },
        {
          "from": "data",
          "text": "The gap is 1 percentage point, but we have only 800 visitors per version so far. A higher number doesn't by itself show the difference is real."
        }
      ],
      "prompt": "What do you do before making a recommendation?",
      "choices": [
        {
          "id": "ask-ai",
          "text": "Ask the AI to check the gap and estimate the sample size we need.",
          "quality": "strong",
          "replies": [
            {
              "from": "ai",
              "text": "I can estimate both. I’ll compare the observed gap with the variation we’d expect by chance, then estimate a useful target sample."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -10
            },
            {
              "meter": "credibility",
              "change": 5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "chance",
              "kind": "good",
              "text": "You checked whether the observed gap could be chance before treating it as a win.",
              "example": null
            },
            {
              "skill": "sample",
              "kind": "good",
              "text": "You asked for a sample-size estimate before deciding how long to run the test.",
              "example": null
            }
          ],
          "next": "ai-check"
        },
        {
          "id": "claim-win",
          "text": "Recommend B now because its conversion rate is higher.",
          "quality": "weak",
          "replies": [
            {
              "from": "product",
              "text": "That would let us move quickly. I’ll bring the recommendation to the review."
            },
            {
              "from": "data",
              "text": "Please call it an early signal, not a proven win. The number of visitors may not be enough to separate a real gap from chance."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": 15
            },
            {
              "meter": "pressure",
              "change": -15
            },
            {
              "meter": "credibility",
              "change": -10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "chance",
              "kind": "improve",
              "text": "You treated a higher early rate as proof. Check whether chance could explain the gap before recommending a launch.",
              "example": "“B is ahead so far, but we need more evidence before calling it a real difference.”"
            }
          ],
          "next": "launch-check"
        },
        {
          "id": "ask-data",
          "text": "Ask the data analyst to set a fair test target before the review.",
          "quality": "strong",
          "replies": [
            {
              "from": "data",
              "text": "I’ll estimate a target from the 1-point gap and agree on one planned check. That helps us avoid stopping just because the results briefly look good."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -10
            },
            {
              "meter": "credibility",
              "change": 5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "sample",
              "kind": "good",
              "text": "You brought in the method expert to set a sample target instead of guessing.",
              "example": null
            },
            {
              "skill": "explain",
              "kind": "good",
              "text": "You asked for a clear decision rule you can share with the product team.",
              "example": null
            }
          ],
          "next": "plan-check"
        }
      ]
    },
    {
      "id": "ai-check",
      "messages": [
        {
          "from": "ai",
          "text": "At 32 of 800 versus 40 of 800, the estimated p-value is about 0.33. In plain language, a gap this large could happen by chance fairly often if the versions were equally effective. It is not a 33% chance that B is better."
        },
        {
          "from": "ai",
          "text": "To detect a 1-percentage-point gap with about 80% power at a 5% significance level, a rough target is 7,000 visitors per version. The exact target depends on the true rates."
        },
        {
          "from": "data",
          "text": "If we continue, keep the audience assignment and checkout the same, and check once at the planned target."
        }
      ],
      "prompt": "What do you recommend to {{product}}?",
      "choices": [
        {
          "id": "fixed-test",
          "text": "Keep the test unchanged until 7,000 visitors per version, then check once.",
          "quality": "strong",
          "replies": [
            {
              "from": "product",
              "text": "That means waiting, but I can explain the timeline and the reason for it."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -25
            },
            {
              "meter": "pressure",
              "change": 15
            },
            {
              "meter": "credibility",
              "change": 20
            }
          ],
          "timeJump": {
            "label": "One week later",
            "panel": {
              "title": "Planned test check",
              "metrics": [
                {
                  "label": "Visitors to A",
                  "value": "7,000",
                  "note": null
                },
                {
                  "label": "Purchases with A",
                  "value": "280",
                  "note": "4.0% conversion"
                },
                {
                  "label": "Visitors to B",
                  "value": "7,000",
                  "note": null
                },
                {
                  "label": "Purchases with B",
                  "value": "350",
                  "note": "5.0% conversion"
                }
              ],
              "note": "Same audience and assignment; checked once at the planned target. Estimated p-value: about 0.004."
            }
          },
          "notes": [
            {
              "skill": "sample",
              "kind": "good",
              "text": "You set a target before looking again, which makes the comparison more reliable.",
              "example": null
            },
            {
              "skill": "chance",
              "kind": "good",
              "text": "At the planned check, the gap is unlikely to be explained by chance under the test assumptions.",
              "example": null
            }
          ],
          "next": "validated"
        },
        {
          "id": "report-early",
          "text": "Report the current result as inconclusive and keep A for now.",
          "quality": "fair",
          "replies": [
            {
              "from": "product",
              "text": "We lose the chance to launch today, but I can share that the first day didn't settle the question."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -8
            },
            {
              "meter": "pressure",
              "change": -5
            },
            {
              "meter": "credibility",
              "change": 8
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "explain",
              "kind": "good",
              "text": "You described what the early test can and cannot tell the team, without overselling it.",
              "example": "“B is ahead so far, but this test hasn't shown that the gap is more than chance.”"
            }
          ],
          "next": "cautious"
        },
        {
          "id": "peek-daily",
          "text": "Check the results every day and stop when B looks significant.",
          "quality": "weak",
          "replies": [
            {
              "from": "data",
              "text": "Repeated checks make a false alarm more likely. If we use this approach, we shouldn't treat a later significant-looking result as a clean confirmation."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": 15
            },
            {
              "meter": "pressure",
              "change": -5
            },
            {
              "meter": "credibility",
              "change": -10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "chance",
              "kind": "improve",
              "text": "Repeatedly checking until a result looks significant can make a chance gap seem convincing. Set the sample target and check time first.",
              "example": "“Let’s check once after we reach 7,000 visitors per version.”"
            }
          ],
          "next": "paused"
        }
      ]
    },
    {
      "id": "launch-check",
      "messages": [
        {
          "from": "product",
          "text": "I told the review B was ahead by 25%. They're asking whether that is enough to switch the checkout."
        },
        {
          "from": "data",
          "text": "It is a real observed gap: 5.0% versus 4.0%. But after just 800 visitors per version, the test hasn't ruled out chance. Let's correct the claim before anyone approves a broad launch."
        }
      ],
      "prompt": "What do you tell the review team now?",
      "choices": [
        {
          "id": "correct-and-test",
          "text": "Clarify that the gap is early, then run to a fixed 7,000 visitors per version.",
          "quality": "strong",
          "replies": [
            {
              "from": "product",
              "text": "I’ll update the review and explain why we need one planned check before a broad launch."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -25
            },
            {
              "meter": "pressure",
              "change": 15
            },
            {
              "meter": "credibility",
              "change": 20
            }
          ],
          "timeJump": {
            "label": "One week later",
            "panel": {
              "title": "Planned test check",
              "metrics": [
                {
                  "label": "Visitors to A",
                  "value": "7,000",
                  "note": null
                },
                {
                  "label": "Purchases with A",
                  "value": "280",
                  "note": "4.0% conversion"
                },
                {
                  "label": "Visitors to B",
                  "value": "7,000",
                  "note": null
                },
                {
                  "label": "Purchases with B",
                  "value": "350",
                  "note": "5.0% conversion"
                }
              ],
              "note": "Same audience and assignment; checked once at the planned target. Estimated p-value: about 0.004."
            }
          },
          "notes": [
            {
              "skill": "explain",
              "kind": "good",
              "text": "You corrected the claim without hiding the observed gap, and gave the team a clear next step.",
              "example": "“B is ahead by 1 percentage point so far, but we need the planned test to tell whether the gap is more than chance.”"
            },
            {
              "skill": "sample",
              "kind": "good",
              "text": "You chose a target rather than relying on a quick early result.",
              "example": null
            }
          ],
          "next": "validated"
        },
        {
          "id": "small-rollout",
          "text": "Offer B to a small share of visitors while keeping the test running.",
          "quality": "fair",
          "replies": [
            {
              "from": "data",
              "text": "A limited rollout can meet the team's need to learn in practice, but keep the early result labeled as uncertain and don't call B a proven winner."
            },
            {
              "from": "product",
              "text": "A smaller step gives us something to do today while we avoid switching everyone at once."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -5
            },
            {
              "meter": "pressure",
              "change": -8
            },
            {
              "meter": "credibility",
              "change": 2
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "chance",
              "kind": "good",
              "text": "You balanced the request to move quickly with the uncertainty in the early numbers.",
              "example": null
            },
            {
              "skill": "explain",
              "kind": "improve",
              "text": "Make clear that a limited rollout is a way to learn, not proof that B is better.",
              "example": "“We can try B with a small share, but the early test is still inconclusive.”"
            }
          ],
          "next": "cautious"
        },
        {
          "id": "keep-claim",
          "text": "Keep the 25% win claim and ask for approval to switch everyone.",
          "quality": "weak",
          "replies": [
            {
              "from": "data",
              "text": "I can't confirm that claim from these counts. The review needs the difference stated as an early result, and a broad switch should wait for a sound check."
            },
            {
              "from": "product",
              "text": "I'll pause the approval request until we can present the result more carefully."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": 15
            },
            {
              "meter": "pressure",
              "change": -15
            },
            {
              "meter": "credibility",
              "change": -15
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "explain",
              "kind": "improve",
              "text": "The 25% figure is a relative gap, not evidence by itself that the difference is real. Pair it with the absolute rates and the test's uncertainty.",
              "example": "“B is at 5.0% and A is at 4.0% so far; we haven't ruled out chance.”"
            }
          ],
          "next": "paused"
        }
      ]
    },
    {
      "id": "plan-check",
      "messages": [
        {
          "from": "data",
          "text": "For a 1-point gap, about 7,000 visitors per version is a reasonable target with these assumptions. We'll keep the versions and audience assignment steady and check once at the target."
        },
        {
          "from": "product",
          "text": "A week is a delay. Could we at least agree on what we will say in today's review?"
        }
      ],
      "prompt": "What plan do you bring to the review?",
      "choices": [
        {
          "id": "agree-target",
          "text": "Set the 7,000-per-version target and report the early gap as uncertain.",
          "quality": "strong",
          "replies": [
            {
              "from": "product",
              "text": "I'll share the target and tell the team the early numbers are not a final answer."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -20
            },
            {
              "meter": "pressure",
              "change": 10
            },
            {
              "meter": "credibility",
              "change": 15
            }
          ],
          "timeJump": {
            "label": "One week later",
            "panel": {
              "title": "Planned test check",
              "metrics": [
                {
                  "label": "Visitors to A",
                  "value": "7,000",
                  "note": null
                },
                {
                  "label": "Purchases with A",
                  "value": "280",
                  "note": "4.0% conversion"
                },
                {
                  "label": "Visitors to B",
                  "value": "7,000",
                  "note": null
                },
                {
                  "label": "Purchases with B",
                  "value": "350",
                  "note": "5.0% conversion"
                }
              ],
              "note": "Same audience and assignment; checked once at the planned target. Estimated p-value: about 0.004."
            }
          },
          "notes": [
            {
              "skill": "sample",
              "kind": "good",
              "text": "You set a practical target based on the gap you want to detect, rather than choosing a number for convenience.",
              "example": null
            },
            {
              "skill": "explain",
              "kind": "good",
              "text": "You gave the team a useful interim message that doesn't overstate the result.",
              "example": "“B is ahead so far, but we're waiting for the planned test check.”"
            }
          ],
          "next": "validated"
        },
        {
          "id": "limited-pilot",
          "text": "Suggest a small pilot now and keep the result labeled as uncertain.",
          "quality": "fair",
          "replies": [
            {
              "from": "product",
              "text": "That gives us a cautious step today. I'll make sure the team knows it isn't a proven win."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -5
            },
            {
              "meter": "pressure",
              "change": -8
            },
            {
              "meter": "credibility",
              "change": 3
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "chance",
              "kind": "good",
              "text": "You allowed a limited next step without presenting the early gap as proof.",
              "example": null
            },
            {
              "skill": "explain",
              "kind": "good",
              "text": "Say plainly that the pilot is exploratory and the main test still needs its planned check.",
              "example": "“This small pilot helps us learn; it doesn't settle whether B is better.”"
            }
          ],
          "next": "cautious"
        },
        {
          "id": "use-current-count",
          "text": "Use the 800 visitors per version as the target to save time.",
          "quality": "weak",
          "replies": [
            {
              "from": "data",
              "text": "That count is where we are now, not a target chosen to detect a 1-point gap. I recommend we report the test as inconclusive rather than claim a winner."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": 12
            },
            {
              "meter": "pressure",
              "change": -10
            },
            {
              "meter": "credibility",
              "change": -10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "sample",
              "kind": "improve",
              "text": "Don't confuse the current sample with a sample-size plan. Choose the target based on the difference you want the test to detect.",
              "example": "“We have 800 per version so far; our rough target for this gap is about 7,000 per version.”"
            }
          ],
          "next": "paused"
        }
      ]
    }
  ],
  "endings": [
    {
      "id": "validated",
      "outcome": "At the planned check, B had 350 purchases from 7,000 visitors (5.0%) and A had 280 from 7,000 (4.0%). The gap is unlikely to be due to chance under the test assumptions, so the team can consider a staged rollout while continuing to monitor results."
    },
    {
      "id": "cautious",
      "outcome": "The team keeps A as the default and treats B as an early signal, or as a limited pilot if you chose that route. The first-day gap did not settle whether B is truly better."
    },
    {
      "id": "paused",
      "outcome": "The review pauses a broad switch. {{data}} points out that the early counts or repeated checks don't support a confident winner claim, so the team labels the result inconclusive and agrees to plan a sounder check."
    }
  ],
  "summary": [
    "A difference between two groups can happen by chance; an early lead alone does not show a real effect.",
    "Choose a sample target and a planned check before judging an experiment.",
    "Explain both the observed gap and its uncertainty in plain language."
  ]
}

{
  "title": "E se você pudesse ver os pacotes de luz?",
  "setting": "Ateliê de luz, numa noite",
  "mission": "Monte um teste para criar um mural luminoso. **Descubra como mostrar tanto os flashes individuais quanto o desenho que eles formam juntos.**",
  "deadline": null,
  "panels": [],
  "team": [
    {
      "id": "artista",
      "role": "Artista de luz",
      "expertise": "Cria desenhos com luz e percebe padrões visuais.",
      "ai": false
    },
    {
      "id": "sensor",
      "role": "Técnico de sensores",
      "expertise": "Sabe registrar flashes fracos sem perder cada chegada.",
      "ai": false
    }
  ],
  "meters": [
    {
      "id": "pistas",
      "label": "Pistas visíveis",
      "start": 40,
      "goodWhen": "high"
    }
  ],
  "skills": [
    {
      "id": "pacotes",
      "name": "Energia em pacotes",
      "practice": "Explique em uma frase por que a luz não entrega energia em qualquer quantidade, como se contasse a ideia para alguém curioso."
    },
    {
      "id": "dualidade",
      "name": "Onda e partícula",
      "practice": "Desenhe dois jeitos de observar a luz: chegadas em flashes e um padrão que aparece com o tempo."
    }
  ],
  "startNodeId": "inicio",
  "nodes": [
    {
      "id": "inicio",
      "messages": [
        {
          "from": "artista",
          "text": "E se a luz chegasse como pontinhos que a gente pudesse ver? Quero transformar isso num mural."
        },
        {
          "from": "sensor",
          "text": "Cada pontinho seria um quantum: um pacote de energia, não uma quantidade que aumenta de qualquer jeito. Vamos ver o que aparece."
        }
      ],
      "prompt": "Como você prepara o primeiro teste para investigar esses flashes?",
      "choices": [
        {
          "id": "contar",
          "text": "Diminuo a luz e conto os flashes enquanto ela passa por duas aberturas estreitas.",
          "quality": "strong",
          "replies": [
            {
              "from": "sensor",
              "text": "Boa. Com pouca luz, dá para registrar cada chegada e deixar o desenho se formar aos poucos."
            }
          ],
          "effects": [
            {
              "meter": "pistas",
              "change": 20
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "pacotes",
              "kind": "good",
              "text": "Você montou o teste para observar chegadas em pacotes, em vez de tratar a luz como um fluxo sem partes.",
              "example": null
            },
            {
              "skill": "dualidade",
              "kind": "good",
              "text": "As duas aberturas permitem observar se aparece um padrão além dos flashes individuais.",
              "example": null
            }
          ],
          "next": "observar"
        },
        {
          "id": "brilho",
          "text": "Aumento bastante o brilho e projeto a luz direto na parede para ver o desenho logo.",
          "quality": "weak",
          "replies": [
            {
              "from": "artista",
              "text": "O mural apareceu rápido, mas tantos flashes juntos ficam difíceis de distinguir."
            }
          ],
          "effects": [
            {
              "meter": "pistas",
              "change": -10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "dualidade",
              "kind": "improve",
              "text": "Com muitos flashes misturados, você perde a chance de notar as chegadas individuais antes de olhar o padrão.",
              "example": "“Vou diminuir a luz para enxergar os flashes e depois observar o desenho que se forma.”"
            }
          ],
          "next": "corrigir"
        }
      ]
    },
    {
      "id": "observar",
      "messages": [
